/**
 * @module
 * Rate Limit Middleware for Hono.
 */

import { HTTPException } from '../../http-exception'
import type { MiddlewareHandler } from '../../types'

export type RateLimitOptions = {
  windowMs?: number
  limit?: number
  keyGenerator?: (c: Parameters<MiddlewareHandler>[0]) => string
}

type Entry = {
  count: number
  resetAt: number
}

/**
 * Rate Limit Middleware for Hono.
 *
 * @param {RateLimitOptions} [options] - Configuration options.
 * @returns {MiddlewareHandler} The middleware handler function.
 *
 * @example
 * ```ts
 * const app = new Hono()
 *
 * app.use('/api/*', rateLimit({ windowMs: 60_000, limit: 100 }))
 * ```
 */
export const rateLimit = (options: RateLimitOptions = {}): MiddlewareHandler => {
  const windowMs = options.windowMs ?? 60_000
  const limit = options.limit ?? 100
  const keyGenerator =
    options.keyGenerator ?? ((c) => c.req.header('x-forwarded-for') ?? 'global')

  const store = new Map<string, Entry>()

  return async function rateLimit(c, next) {
    const key = keyGenerator(c)
    const now = Date.now()
    let entry = store.get(key)

    if (!entry || entry.resetAt <= now) {
      entry = { count: 0, resetAt: now + windowMs }
      store.set(key, entry)
    }

    entry.count++

    const remaining = Math.max(0, limit - entry.count)
    c.header('X-RateLimit-Limit', String(limit))
    c.header('X-RateLimit-Remaining', String(remaining))
    c.header('X-RateLimit-Reset', String(Math.ceil(entry.resetAt / 1000)))

    if (entry.count > limit) {
      throw new HTTPException(429, { message: 'Too Many Requests' })
    }

    await next()
  }
}

